package com.naimat.autotimelinesync;
import android.net.Uri;import org.json.*;import java.util.*;
public final class Project {
 public String script="";public Uri narration,music,folder;public JSONObject overrides=new JSONObject();public ATSModel model;public MediaFiles media;public boolean fit=false;
 public Project(MediaFiles m){media=m;}
 public ATSModel resolve()throws Exception{JSONObject j=StrictJson.object(script);for(String group:new String[]{"caption_style","direction","style","audio"}){JSONObject base=ATSModel.obj(j,group),changes=overrides.optJSONObject(group);if(changes!=null){Iterator<String>it=changes.keys();while(it.hasNext()){String k=it.next();base.put(k,changes.get(k));}j.put(group,base);}}if(overrides.has("orientation")){String orientation=overrides.getString("orientation");String ratio=orientation.equals("HORIZONTAL")?"16:9":orientation.equals("SQUARE")?"1:1":orientation.equals("PORTRAIT")?"4:5":"9:16";j.put("format",new JSONObject().put("orientation",orientation).put("aspect_ratio",ratio));}model=ATSModel.parse(j.toString());return model;}
 public void set(String group,String key,Object value)throws Exception{JSONObject changes=ATSModel.obj(overrides,group);changes.put(key,value);overrides.put(group,changes);resolve();}
 public JSONObject save()throws Exception{JSONObject images=new JSONObject();for(Map.Entry<String,Uri>e:media.images.entrySet())images.put(e.getKey(),e.getValue().toString());return new JSONObject().put("project_format",2).put("platform","Android").put("name",model==null?"New project":model.title).put("script",StrictJson.object(script)).put("narration",narration==null?JSONObject.NULL:narration.toString()).put("music",music==null?JSONObject.NULL:music.toString()).put("image_folder",folder==null?JSONObject.NULL:folder.toString()).put("images",images).put("overrides",overrides).put("framing",fit?"FIT":"CROP");}
 public void load(String content)throws Exception{JSONObject j=StrictJson.object(content);if(j.optInt("project_format")!=2)throw new Exception("Unsupported project format.");Object s=j.opt("script");script=s instanceof JSONObject?s.toString():j.optString("script","");narration=uri(j,"narration");music=uri(j,"music");folder=uri(j,"image_folder");overrides=ATSModel.obj(j,"overrides");fit=j.optString("framing").equals("FIT");media.images.clear();JSONObject imgs=j.optJSONObject("images");if(imgs!=null){Iterator<String>i=imgs.keys();while(i.hasNext()){String key=i.next();media.images.put(key,Uri.parse(imgs.getString(key)));}}else if(folder!=null)media.folder(folder);resolve();}
 static Uri uri(JSONObject j,String k){String s=j.optString(k,"");return s.isEmpty()||s.equals("null")?null:Uri.parse(s);}
}
